import {subnet,fragments,checksum,delay,shortest} from './core.js';
export const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function workedHTML(w){if(!w)return '';return `<dl class="worked">${[['Dữ liệu từ đề',w.given],['Ý nghĩa ký hiệu',w.symbols],['Đổi đơn vị / hệ đếm',w.conversion],['Công thức / quy tắc',w.formula],['Thay số',w.substitution],['Kết quả',w.result]].map(([k,v])=>`<div><dt>${k}</dt><dd>${escapeHTML(v)}</dd></div>`).join('')}</dl>`}
const table=(heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${escapeHTML(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${escapeHTML(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const W=(given,symbols,conversion,formula,substitution,result)=>workedHTML({given,symbols,conversion,formula,substitution,result});
export function solveCalc(kind,fd){let n=k=>Number(fd.get(k)),str=k=>String(fd.get(k)||'').trim();
if(kind==='subnet'){let p=n('prefix'),k=n('subnets');if(!Number.isInteger(k)||k<1||k>256)throw Error('Chọn 1–256 subnet để hiển thị.');let parent=subnet(str('ip'),p),s=Math.ceil(Math.log2(k)),np=p+s;if(np>32)throw Error('Không đủ bit host để chia số subnet này.');let base=parent.network.split('.').reduce((a,b)=>a*256+Number(b),0),size=2**(32-np),num=2**s,rows=[];for(let i=0;i<num;i++){let ip=[24,16,8,0].map(j=>Math.floor((base+i*size)/2**j)%256).join('.'),r=subnet(ip,np);rows.push([ip+'/'+np,r.first+' – '+r.last,r.broadcast,r.hosts])}return W(`IP=${str('ip')}/${p}; yêu cầu ít nhất ${k} subnet bằng nhau.`,'p: prefix cũ; k: số subnet tối thiểu; s: bit mượn; B: địa chỉ/subnet.','IPv4 có 32 bit; địa chỉ đổi sang nhị phân để AND với mask khi tìm mạng gốc.','Network=IP AND mask; s=ceil(log₂k); p_new=p+s; B=2^(32−p_new).',`Mạng gốc ${parent.network}/${p}; s=${s}; p_new=${p}+${s}=${np}; B=2^${32-np}=${size}.`,`${num} subnet /${np}; mask ${subnet(parent.network,np).mask}.`)+(np>=31?'<p>/31 dùng cho điểm-điểm; /32 là một địa chỉ. Không trừ 2 và không dùng broadcast thông thường.</p>':'<p>Subnet thông thường: host dùng được = B−2 (bỏ network/broadcast).</p>')+table(['Mạng con','Dải host','Broadcast','Host dùng được'],rows)}
if(kind==='delay'){let b=n('bytes'),r=n('rate'),d=n('km'),s=n('speed'),N=n('links'),P=n('packets'),x=delay(b,r,d,s,N,P),ms=t=>(t*1000).toLocaleString('vi-VN',{maximumFractionDigits:6});return W(`Mỗi gói ${b} byte; R=${r} Mbps; d=${d} km/link; s=${s} m/s; N=${N}; P=${P}.`,'L: bit/gói; R: bit/s; d: mét; s: m/s; N: link; P: gói; T: thời gian nhận đủ.',`L=${b}×8=${b*8} bit; R=${r}×10⁶=${r*1e6} bit/s; d=${d}×1000=${d*1000} m. 1 s=1000 ms.`,'t_trans=L/R; t_prop=d/s; T_1=N(t_trans+t_prop); T_P=(N+P−1)t_trans+N·t_prop.',`t_trans=${b*8}/${r*1e6}=${x.tx} s; t_prop=${d*1000}/${s}=${x.prop} s. T_1=${N}×(${x.tx}+${x.prop}); T_P=(${N}+${P}−1)×${x.tx}+${N}×${x.prop}.`,`Trễ truyền ${ms(x.tx)} ms/link; lan truyền ${ms(x.prop)} ms/link. Một gói ${ms(x.one)} ms; ${P} gói ${ms(x.all)} ms.`)+'<p class="muted">Giả định store-and-forward, link đồng tốc/cùng chiều dài, gói cùng cỡ gửi liên tiếp, không trễ xử lý/hàng đợi.</p>'}
if(kind==='fragment'){let T=n('total'),M=n('mtu'),H=n('header'),ID=n('ident');if(!Number.isInteger(ID)||ID<0||ID>65535)throw Error('ID từ 0–65535.');let rows=fragments(T,M,H),D=T-H,C=Math.floor((M-H)/8)*8;return W(`Total=${T} byte; MTU=${M} byte; header=${H} byte; ID=${ID}; DF=0.`,'T: datagram gốc có header; H: header/mảnh; D: dữ liệu gốc; C: payload tối đa mảnh không cuối; o: offset.','T,H,MTU cùng byte. Offset đo bằng khối 8 byte; mảnh không cuối phải có payload bội 8.','D=T−H; C=floor((MTU−H)/8)×8; n=ceil(D/C) khi T>MTU; o=byte dữ liệu trước mảnh /8.',`D=${T}−${H}=${D}; C=floor((${M}−${H})/8)×8=${C}. ${T<=M?'T≤MTU, không cần tách.':`n=ceil(${D}/${C})=${rows.length}.`}`,`${rows.length} mảnh; ID chung ${ID}.`)+table(['Mảnh','Total length','Dữ liệu','Offset','MF'],rows.map((r,i)=>[i+1,r.length,r.data,r.offset,r.mf]))+'<p class="muted">Header cùng chiều dài, bỏ xử lý IP options phức tạp; ghép tại đích. MF=1 nghĩa còn mảnh sau.</p>'}
if(kind==='checksum'){let input=str('words');if(!input||input.length>10000||!input.split(/\s+/).every(x=>/^[0-9a-f]{1,4}$/i.test(x)))throw Error('Nhập từ hex 0000–FFFF cách bằng dấu cách, tối đa 10000 ký tự.');let words=input.split(/\s+/).map(x=>parseInt(x,16)),hex=x=>x.toString(16).toUpperCase().padStart(4,'0'),c=checksum(words),sum=0,rows=[];words.forEach((word,i)=>{let raw=sum+word;sum=(raw&65535)+(raw>>>16);if(sum>65535)sum=(sum&65535)+1;rows.push([i+1,hex(word),raw.toString(16).toUpperCase(),hex(sum)])});return W(`Các từ 16 bit: ${input}.`,'S: tổng bù 1 sau cộng vòng; C: checksum.','Mỗi nhóm hex tối đa 4 chữ số = 16 bit. Bit nhớ vượt bit 15 được cộng vào phần thấp.','S=fold16(Σwords); C=FFFF−S; bên nhận cộng dữ liệu cùng C rồi kiểm tra FFFF.',`S=0x${hex(sum)}; C=0xFFFF−0x${hex(sum)}.`,`Checksum: 0x${hex(c)}; cộng dữ liệu + checksum được FFFF (không phát hiện lỗi).`)+table(['Từ','Word hex','Tổng trước cộng vòng','Sau cộng vòng'],rows)+'<p class="muted">Bài tính rút gọn theo các từ đã nhập. TCP/UDP thực tế còn tính pseudo-header. Muốn kiểm tra gói đã có checksum, nhập cả checksum; kết quả 0000 nghĩa tổng FFFF, không chứng minh không có lỗi.</p>'}
let items=str('edges').split(',');if(items.length>100)throw Error('Tối đa 100 cạnh.');let seen=new Set(),edges=items.map(x=>{let m=x.trim().match(/^([a-zA-Z0-9]{1,12})-([a-zA-Z0-9]{1,12}):(\d+(?:\.\d+)?)$/);if(!m||!Number.isFinite(+m[3])||+m[3]>1e9)throw Error('Cạnh đúng dạng u-v:2, tên 1–12 ký tự, chi phí 0–10⁹.');let id=[m[1],m[2]].sort().join('-');if(seen.has(id))throw Error('Không nhập cạnh trùng cho đồ thị vô hướng.');seen.add(id);return [m[1],m[2],+m[3]]}),start=str('start');if(!edges.some(e=>e[0]===start||e[1]===start))throw Error('Nút nguồn phải có trong các cạnh.');let r=shortest(edges,start),route=v=>{if(!Number.isFinite(r.dist[v]))return 'Không tới được';let p=[v];while(Object.hasOwn(r.prev,p[0]))p.unshift(r.prev[p[0]]);return p.join(' → ')};return W(`Nguồn=${start}; các cạnh ${str('edges')}.`,'c(a,b): chi phí cạnh; D(v): khoảng cách tạm; p(v): nút trước; N′: tập đã chốt.','Các chi phí cùng đơn vị trừu tượng, không cần đổi. Cạnh vô hướng, trọng số không âm.','Chọn w chưa chốt có D nhỏ nhất; D(v)=min(D(v),D(w)+c(w,v)).',`Khởi tạo D(${start})=0, nút khác=∞. Bảng bên dưới ghi D sau khi relax từng nút đã chọn.`,'Khoảng cách và đường đi tối ưu trong bảng cuối; đồng chi phí có thể có nhiều đường.')+table(['Bước','Chốt nút','Khoảng cách sau cập nhật'],r.steps.map((s,i)=>[i+1,s.u,Object.entries(s.dist).map(([k,v])=>k+': '+v).join(' | ')]))+table(['Đích','Chi phí','Đường đi'],Object.entries(r.dist).map(([v,c])=>[v,c,route(v)]))}
